function() {
  var cUserId = {{[VAR] Cookie - userID}};
  var dtUser_id = {{user_id}};
  var dtUserInfoUser_id = {{[VAR] dataLayer - userInfo.user_id}};
  var invalidValuesRegex = /^(|unidentified|undefined|null|not set|no id|guest)$/i;

  function isValidUserId(value) {
    return !(value === null || 
             value === undefined || 
             String(value).trim() === '' || 
             invalidValuesRegex.test(String(value).trim()));
  }

  if (isValidUserId(cUserId)) {
    return cUserId;
  } 
  else if (isValidUserId(dtUser_id)) {
    return dtUser_id;
  } 
  else if (isValidUserId(dtUserInfoUser_id)) {
    return dtUserInfoUser_id;
  }
  else {
    return undefined;
  }
}
